->name}}</strong><div class="text-muted">{{$c->against->email}}</div></div></div>@else — @endif</td><td>{{$c->type?->name}}</td><td><span class="cmp-date">{!!$ic['cal']!!}{{$d['complaint_date']}}</span></td><td>@if($c->document_path)<a target="_blank" href="{{route('complaints-document',$c)}}">{!!$ic['doc']!!}</a>@else — @endif</td><td><div class="d-flex gap-3">@foreach(['view'=>'View','edit'=>'Edit','status'=>'Status','assign'=>'Assign','resolve'=>'Resolve','follow'=>'Follow-up'] as $action=>$title)<button class="cmp-action" data-bs-toggle="modal" data-bs-target="#cmp{{ucfirst($action)}}Modal" data-item="{{base64_encode(json_encode($d))}}" onclick="cmpAction('{{$action}}',this.dataset.item)" title="{{$title}}">{!!$ic[$action]!!}</button>@endforeach<form method="POST" action="{{route('complaints-destroy',$c)}}" class="cmp-delete" data-name="{{$c->subject}}">@csrf @method('DELETE')<button class="cmp-action" title="Delete">{!!$ic['delete']!!}</button></form></div></td></tr>@empty<tr><td colspan="7" class="text-center py-10 text-muted">No complaints found.</td></tr>@endforelse</tbody></table></div><div class="d-flex justify-content-between align-items-center p-5"><span class="text-muted">Showing {{$complaints->firstItem()??0}} to {{$complaints->lastItem()??0}} of {{$complaints->total()}} results</span>{{$complaints->links('pagination::bootstrap-4')}}</div></div></div>
