@foreach([['status','Change Complaint Status','complaints-status'],['assign','Assign Complaint','complaints-assign'],['resolve','Resolve Complaint','complaints-resolve'],['follow','Update Follow-up Information','complaints-follow-up']] as $m)<div class="modal fade cmp-modal" id="cmp{{ucfirst($m[0])}}Modal"><div class="modal-dialog modal-dialog-centered modal-sm"><div class="modal-content"><form id="cmp{{ucfirst($m[0])}}Form" method="POST">@csrf @method('PATCH')<div class="modal-header"><h2 class="fs-4 mb-0">{{$m[1]}}</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">@if($m[0]==='status')<label class="form-label required">Status</label><select class="form-select" name="status">@foreach(['Submitted','Under Investigation','Resolved','Dismissed'] as $s)<option>{{$s}}</option>@endforeach</select>@elseif($m[0]==='assign')<div class="mb-5"><label class="form-label required">Assign To</label><select class="form-select" name="assigned_to">{!!$employeeOptions!!}</select></div><label class="form-label">Resolution Deadline</label><input class="form-control" type="date" name="resolution_deadline">@elseif($m[0]==='resolve')@foreach([['resolution_type','Resolution Type','input'],['investigation_notes','Investigation Notes','textarea'],['resolution_action','Resolution Action','textarea'],['resolution_date','Resolution Date','date'],['follow_up_action','Follow-up Action','textarea'],['follow_up_date','Follow-up Date','date']] as $f)<div class="mb-5"><label class="form-label {{in_array($f[0],['resolution_type','investigation_notes','resolution_action','resolution_date'])?'required':''}}">{{$f[1]}}</label>@if($f[2]==='textarea')<textarea class="form-control" rows="3" name="{{$f[0]}}"></textarea>@else<input class="form-control" type="{{$f[2]}}" name="{{$f[0]}}">@endif</div>@endforeach @else @foreach([['follow_up_action','Follow-up Action','textarea'],['follow_up_date','Follow-up Date','date'],['feedback','Feedback','textarea']] as $f)<div class="mb-5"><label class="form-label {{$f[0]!=='feedback'?'required':''}}">{{$f[1]}}</label>@if($f[2]==='textarea')<textarea class="form-control" rows="3" name="{{$f[0]}}"></textarea>@else<input class="form-control" type="date" name="{{$f[0]}}">@endif</div>@endforeach @endif</div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success">Save</button></div></form></div></div></div>@endforeach
<script>const cmpRoutes={store:@json(route('complaints-store')),update:@json(route('complaints-update','__ID__')),status:@json(route('complaints-status','__ID__')),assign:@json(route('complaints-assign','__ID__')),resolve:@json(route('complaints-resolve','__ID__')),follow:@json(route('complaints-follow-up','__ID__'))};function cd(x){return x?JSON.parse(atob(x)):{} }function openCmp(x){let d=cd(x),f=cmpForm;f.reset();f.action=cmpRoutes.store;cmpMethod.innerHTML='';cmpTitle.textContent=d.id?'Edit Complaint':'Add New Complaint';['complainant_id','against_id','complaint_type_id','subject','complaint_date','description'].forEach(k=>f.elements[k].value=d[k]||'');f.querySelector('[type=checkbox]').checked=!!d.is_anonymous;if(d.id){f.action=cmpRoutes.update.replace('__ID__',d.id);cmpMethod.innerHTML='<input type="hidden" name="_method" value="PUT">'}}function cmpAction(a,x){let d=cd(x);if(a==='edit'){openCmp(x);return}if(a==='view'){let m=cmpViewModal,v={complainant:d.complainant,against:d.against,type:d.type,date:d.complaint_date,status:d.status,assignee:d.assignee,subject:d.subject,description:d.description,resolution:d.resolution_action,follow:d.follow_up_action,feedback:d.feedback};Object.keys(v).forEach(k=>m.querySelector('[data-cv='+k+']').textContent=v[k]||'—');m.querySelector('[data-cv=document]').innerHTML=d.document_url?(/\.(png|jpe?g)$/i.test(d.document_path)?'<a target="_blank" href="'+d.document_url+'"><img class="cmp-preview" src="'+d.document_url+'"></a>':'<a target="_blank" href="'+d.document_url+'">View document</a>'):'—';return}let f=document.getElementById('cmp'+a[0].toUpperCase()+a.slice(1)+'Form');f.action=cmpRoutes[a].replace('__ID__',d.id);Array.from(f.elements).forEach(el=>{if(el.name&&d[el.name]!=null)el.value=d[el.name]});}document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.cmp-delete').forEach(f=>f.onsubmit=e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete complaint',text:'Are you sure you want to delete '+f.dataset.name+'? This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){f.dataset.ok=1;f.submit()}})});cmpForm.onsubmit=e=>{let anon=cmpForm.querySelector('[type=checkbox]').checked,req={complaint_type_id:'Complaint Type',subject:'Subject',complaint_date:'Complaint Date',description:'Description'};if(!anon)req.complainant_id='Complainant';let missing=Object.entries(req).find(([k])=>!cmpForm.elements[k].value.trim());if(missing){e.preventDefault();Swal.fire({icon:'error',text:missing[1]+' is required'})}}})</script>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.cmp-action[title="Edit"]').forEach(function(button){button.setAttribute('data-bs-target','#cmpFormModal')})});</script>
